   sql="SELECT count(*) FROM examen_resultado r JOIN orden_examen o ON o.id_orden_examen=r.id_orden_examen JOIN consulta_procedimiento_paso p ON p.id_consulta_procedimiento_paso=o.id_consulta_procedimiento_paso JOIN consulta_procedimiento cp ON cp.id_consulta_procedimiento=p.id_consulta_procedimiento WHERE r.resultado='DESARROLLO resultado "+token+"' AND cp.id_consulta='"+target['idConsulta']+"'"
   count=subprocess.check_output(['docker','exec','postgres_db','psql','-U','postgres','-d','clinica','-At','-c',sql],text=True).strip();self.assertEqual(count,'1');self.assertEqual(errors,[]);page.screenshot(path='/private/tmp/galenos-flujo-clinica.png',full_page=True);b.close()
